import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CAKCj7G0.js";const h=JSON.parse('{"title":"2-1. React-router介绍","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/11.react(谢杰)/codestation前台/2-1. React-router介绍.md","filePath":"DuOneClass/11.react(谢杰)/codestation前台/2-1. React-router介绍.md"}'),m={name:"DuOneClass/11.react(谢杰)/codestation前台/2-1. React-router介绍.md"};function c(l,e,n,s,i,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_2-1-react-router介绍" tabindex="-1">2-1. React-router介绍 <a class="header-anchor" href="#_2-1-react-router介绍" aria-label="Permalink to &quot;2-1. React-router介绍&quot;">​</a></h1><h1 id="react-router-v6" tabindex="-1"><em>React-router v6</em> <a class="header-anchor" href="#react-router-v6" aria-label="Permalink to &quot;*React-router v6*&quot;">​</a></h1><ul><li>前端路由概念</li><li><em>React-router</em></li></ul><h2 id="前端路由概念" tabindex="-1">前端路由概念 <a class="header-anchor" href="#前端路由概念" aria-label="Permalink to &quot;前端路由概念&quot;">​</a></h2><p>早期的时候并不存在前端路由，那个时候只有后端路由，类似于下图：</p><p><img src="https://s2.loli.net/2024/09/05/MwnA7e8fSORGmEl.png" alt=""></p><p>后来，随着单页应用的流行，整个 <em>Web</em> 应用之存在一个页面，通过 <em>JS</em> 调整模块来显示不同的内容，类似于下图：</p><p><img src="https://s2.loli.net/2024/09/05/PSOp2zCXwuyeqZg.png" alt=""></p><p>可以看到，所谓前端路由实际上就是协调当前页面显示什么模块。那么单页应用时代，还存在后端路由么？</p><p>实际上也是存在的，后端路由负责返回对应的数据，如下图：</p><p><img src="https://s2.loli.net/2024/09/05/LX63fPzEmheJB2t.png" alt=""></p><h2 id="react-router" tabindex="-1"><em>React-router</em> <a class="header-anchor" href="#react-router" aria-label="Permalink to &quot;*React-router*&quot;">​</a></h2><p><em>React-router</em> 是 <em>React</em> 官方所推出的前端路由库，官网地址：<em><a href="https://reactrouter.com/en/main" target="_blank" rel="noreferrer">https://reactrouter.com/en/main</a></em></p><p>目前最新的版本为 <em>v6</em> 版本。相比之前的版本，该版本变化略大，加入了许多新的 <em>Hook</em>，比如 <em>useRoutes</em> 这个 <em>Hook</em> 就提供了类似于 <em>Vue-router</em> 相似的特性，从而使得使用起来更加的方便。</p><p>整个官网可以分为几大块：</p><ul><li><em>Components</em> 组件</li><li><em>Hooks</em> 函数</li><li><em>API</em> 函数</li></ul><p>整个 <em>React-router</em>，我们将写一个学生管理系统，用到什么讲什么。</p>',17)])])}const _=t(m,[["render",c]]);export{h as __pageData,_ as default};
